-- Scontro a squadre (SPEC §5.19, docs/COMBAT.md), stage 5, batch 3: the kits of the last 18 Delta
-- characters and the first 7 Gamma characters players own most after the second batch
-- (src/lib/combat-kits-batch-3.ts on 24 November 2026, described in docs/COMBAT-KITS.md). Each one
-- was simulated on its own card: with its kit, in a random team against a random team, it wins
-- between 46% and 56%.
--
-- A kit an admin already saved from the EDITOR for one of these characters stays as it is.

insert into public.combat_kits (definition_id, kit)
select d.id, k.kit::jsonb
