join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P066', 'P134', 'P149', 'P156', 'P143', 'P190', 'P133', 'P135', 'P194', 'P146', 'P151', 'P157', 'P105', 'P148', 'P188', 'P199', 'P071', 'P189', 'P040', 'P191', 'P087', 'P206', 'P036', 'P138', 'P144')) <> 25 then
    raise exception 'a character of the third batch has no kit';
  end if;
end $$;
